input.sparql:
SELECT ?ts_id ?point WHERE {
  ?point brick:isPointOf <urn:perimeter-bot:Zone:Perimeter_bot_ZN_2> ;
         brick:hasMeasurementUnit ?unit ;
         ref:hasTimeseriesId ?timeseries ;
         rdfs:label ?label .
  ?timeseries ref:hasExternalReference ?ts_id .
  FILTER (strSTARTSWITH(str(?unit), "Celsius") && REGEX(?label, "air temperature"))
}

SELECT ?ts_id ?point WHERE {
  ?point brick:isPointOf <urn:perimeter-bot:Zone:Perimeter_bot_ZN_2> ;
         brick:hasMeasurementUnit ?unit ;
         ref:hasTimeseriesId ?timeseries ;
         rdfs:label ?label .
  ?timeseries ref:hasExternalReference ?ts_id .
  FILTER (CONTAINS(str(?unit), 'Celsius') && CONTAINS(lcase(?label), 'air temperature'))
}
